import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {spawnSync} from 'node:child_process';import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(import.meta.url)),root=path.resolve(here,'../..'),mode=process.argv[2],canonical='5bce83410802b04c2d0c7fb0324610f87917a386';
const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const write=(name,value)=>fs.writeFileSync(path.join(here,name),JSON.stringify(value,null,2)+'\n',{flag:'wx'});
const read=file=>JSON.parse(fs.readFileSync(file,'utf8'));
function files(dir){if(!fs.existsSync(dir))return [];const rows=[];for(const e of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())rows.push(...files(p));else rows.push(p);}return rows;}
function inventory(){return files(root).filter(p=>!p.startsWith(here+path.sep)).sort().map(p=>({relative:path.relative(root,p).replaceAll('\\','/'),bytes:fs.statSync(p).size,sha256:hash(fs.readFileSync(p))}));}
function batches(){return ['blocking','expanded','continuous-supplement'].flatMap(kind=>files(path.join(root,kind,'runs')).filter(p=>path.basename(p)==='batch.json').map(file=>({kind,file,b:read(file)})));}
function discovery(){const finalSelection=JSON.parse(fs.readFileSync(path.join(here,'explicit-final-review-selection.json'),'utf8'));if(finalSelection.canonicalSha!==canonical)throw new Error('Selection canonical drift');const relative=file=>path.relative(root,file).replaceAll('\\','/');const all=batches();if(all.length!==4||all.some(q=>!finalSelection.batchRunIds.includes(q.b.runId)))throw new Error('Exact four stopped batches required');const reviews=['blocking','expanded','continuous-supplement'].flatMap(kind=>files(path.join(root,kind,'reviews')).filter(p=>p.endsWith('.json'))).flatMap(file=>{const r=read(file);return r.method==='independent_semantic_review'&&r.canonicalSha===canonical?[{file,sha256:hash(fs.readFileSync(file)),criteriaSha256:hash(JSON.stringify(r.criteria)),r}]:[];});const matched=[],external=[],historical=[];
 for(const review of reviews){const possible=all.filter(q=>q.b.source.canonicalSha===canonical&&q.b.cases[review.r.variant]?.attempts.some(a=>a.attemptId===review.r.attemptId));if(!possible.length){external.push({file:review.file,sha256:review.sha256,variant:review.r.variant,attemptId:review.r.attemptId??null,status:review.r.status,reason:'No actual attempt; external review only, never grade.'});continue;}if(possible.length!==1)throw new Error('ambiguous batch');const q=possible[0],key=[canonical,review.r.variant,review.r.attemptId].join('|');const selected=finalSelection.sameAttemptFinal.find(v=>v.key===key);if(selected&&relative(review.file)===selected.preservedEarlierReview){if(review.sha256!==selected.preservedEarlierSha256)throw new Error('Historical original review drift');historical.push({...review,key,kind:q.kind,batchFile:q.file,finalReviewFile:path.join(root,selected.selectedFinalReview),finalReviewSha256:selected.selectedFinalSha256,reason:'Root explicitly selected independent supplement as the final same-attempt assessment; original PASS bytes/criteria remain historical and are not a new UUID or model call.'});continue;}if(selected&&(relative(review.file)!==selected.selectedFinalReview||review.sha256!==selected.selectedFinalSha256))throw new Error('Exact selected independent supplement required');if(matched.some(m=>m.key===key))throw new Error('Unresolved duplicate independent reviews; no overwrite');matched.push({...review,key,kind:q.kind,batchFile:q.file,attempt:q.b.cases[review.r.variant].attempts.find(a=>a.attemptId===review.r.attemptId)});}
 const missing=all.flatMap(q=>Object.entries(q.b.cases).flatMap(([variant,s])=>s.attempts.filter(a=>!matched.some(m=>m.key===[canonical,variant,a.attemptId].join('|'))).map(a=>({kind:q.kind,batchFile:q.file,variant,attemptId:a.attemptId,uuid:a.threadId,inputs:a.turns.length}))));if(matched.length!==15||historical.length!==0||missing.length)throw new Error('Exactly fifteen unique final reviews and no same-attempt supersession required');return {all,matched,external,missing,historical};}
function compact(d){return {actualReviews:d.matched.map(m=>({file:m.file,sha256:m.sha256,criteriaSha256:m.criteriaSha256,canonicalSha:m.r.canonicalSha,variant:m.r.variant,attemptId:m.r.attemptId,status:m.r.status,reviewer:m.r.reviewer,kind:m.kind,batchFile:m.batchFile,uuid:m.attempt.threadId,actualInputs:m.attempt.turns.length})),external:d.external,missing:d.missing,historicalOriginalReviews:d.historical.map(m=>({file:m.file,sha256:m.sha256,criteriaSha256:m.criteriaSha256,key:m.key,variant:m.r.variant,attemptId:m.r.attemptId,status:m.r.status,finalReviewFile:m.finalReviewFile,finalReviewSha256:m.finalReviewSha256,reason:m.reason,notANewAttempt:true}))};}
if(mode==='before'){
 const inv=inventory(),d=discovery();fs.mkdirSync(path.join(here,'before-batches'),{recursive:true});fs.mkdirSync(path.join(here,'original-reviews'),{recursive:true});
